const squiz = squizStoryRenderer(comp.main);

export default {
  title: "dxp components/Global Alert",
};

const infoHtml = await squiz.markup(infoArgs);

export const Info = {
  render: () => squiz(infoArgs),
  args: infoArgs,
  argTypes: {
    alertType: { control: "select", options: ["Info", "Warning", "Critical", "Info-alt"] },
    title: { control: "text" },
    message: { control: "text" },
    link: { control: "object", description: 'SquizLink object: { text, url, target? }.' },
    actionButton: { control: "object", description: 'SquizLink object: { text, url, target? }.' },
    dismissible: { control: "boolean" },
  },
  parameters: {
    docs: {
      description: { story: "Info variant, with an inline link at the end of the message." },
      source: { code: infoHtml, language: "html", type: "code" },
    },
  },
};

