/**
 * Stacking multiple alerts isn't a distinct input/state of this component --
 * it's achieved by placing several instances in sequence (see
 * global-alert.spec.md _specAssumptions ref 3). This story demonstrates
 * that composition directly, matching the design's own "Multiple site wide
 * alerts" example (ordered most severe first), rather than adding a
 * dedicated preview for something that isn't a single-instance input state.
 */
const stackedCriticalArgs = {
  alertType: "Critical",
  title: "Cyclone warning",
  message: "Residents are advised to seek shelter immediately.",
  link: { text: "More information", url: "https://example.com/cyclone-warning" },
};
const stackedWarningArgs = {
  alertType: "Warning",
  title: "Website outage",
  message: "We are experiencing technical difficulties. Some pages may not be available.",
};
const stackedInfoAltArgs = {
  alertType: "Info-alt",
  title: "MFA required",
  message: "Multi-factor authentication will be required soon to access services.",
  link: { text: "Set up MFA", url: "https://example.com/set-up-mfa" },
};

export const Stacked = {
  render: () =>
    html`<div>
      ${squiz(stackedCriticalArgs)} ${squiz(stackedWarningArgs)} ${squiz(stackedInfoAltArgs)}
    </div>`,
  parameters: {
    docs: {
      description: {
        story: "Three instances placed in sequence, ordered most severe first -- how multiple site-wide alerts are expected to be arranged in a shared template region.",
      },
    },
  },
};
