import { componentAttrs } from "../_utils/component.helper";

function esc(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/\"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

const CLOSE_ICON_SVG =
  '<svg viewBox="0 0 16 16" width="16" height="16" fill="none" aria-hidden="true" focusable="false"><path d="M3 3l10 10M13 3 3 13" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg>';

const ALERT_TYPE_CLASS = {
  Info: "info",
  Warning: "warning",
  Critical: "critical",
  "Info-alt": "info-alt",
};

export default {
  async main(input = {}) {
    const {
      alertType = "Info",
      title = "Global alert title",
      message = "",
      link = null,
      actionButton = null,
      dismissible = true,
    } = input;

    const type = ALERT_TYPE_CLASS[alertType] || "info";
    const resolvedLink = resolveLink(link);
    const resolvedAction = resolveLink(actionButton);
    const alertId = hashString(`${title}:${message}`);

    const linkHtml = resolvedLink
      ? ` <a class="global-alert__link" href="${esc(resolvedLink.url)}"${targetAttrs(resolvedLink.target)}>${esc(resolvedLink.text)}</a>`
      : "";

    const actionHtml = resolvedAction
      ? `<div class="global-alert__action">
        <a class="button button-secondary" href="${esc(resolvedAction.url)}"${targetAttrs(resolvedAction.target)}>${esc(resolvedAction.text)}</a>
      </div>`
      : "";

    const dismissHtml = dismissible
      ? `<button type="button" class="global-alert__dismiss" aria-label="Dismiss alert">
        ${CLOSE_ICON_SVG}
      </button>`
      : "";

    return /*html*/ `
<div ${componentAttrs("global-alert", input)} class="global-alert global-alert--${type}" data-global-alert-id="${alertId}" role="region" aria-label="${esc(title)}">
  <div class="global-alert__content">
    <p class="global-alert__title" data-sq-field="title">${esc(title)}</p>
    <p class="global-alert__message" data-sq-field="message">${esc(message)}${linkHtml}</p>
    ${actionHtml}
  </div>
  ${dismissHtml}
</div>
`;
  },
};

/**
 * SquizLink resolves to a plain string (bare URL) or a { text, url, target }
 * object -- same shape/handling as `quick-exit`'s own resolveLink(), plus a
 * `text` fallback since, unlike quick-exit's fixed-label banner button, this
 * component's link/button text is entirely editor-supplied (e.g. "More
 * information", "Set up MFA").
 */
function resolveLink(link) {
  if (!link) return null;
  if (typeof link === "string") return { url: link, text: link, target: "_self" };
  if (typeof link === "object" && link.url) {
    return { url: link.url, text: link.text || link.url, target: link.target || "_self" };
  }
  return null;
}

function targetAttrs(target) {
  return target && target !== "_self" ? ` target="${esc(target)}" rel="noopener noreferrer"` : "";
}

/**
 * A stable, non-cryptographic identifier for this alert instance (title +
 * message), embedded as a data attribute so global-alert.js can key
 * sessionStorage dismissal per-alert -- not per-component-type, since a page
 * can have several global-alert instances stacked at once (see
 * global-alert.spec.md assumption 3). No dependency on crypto.subtle, which
 * isn't guaranteed synchronously available in every edge runtime.
 */
function hashString(value) {
  let hash = 0;
  const str = String(value ?? "");
  for (let i = 0; i < str.length; i++) {
    hash = (hash * 31 + str.charCodeAt(i)) | 0;
  }
  return Math.abs(hash).toString(36);
}
